fn encode_cyclic(s: Vec<i8>) -> Vec<i8> {
    let mut result = Vec::with_capacity(s.len());
    for chunk in s.chunks(3) {
        if chunk.len() == 3 {
            // For a full 3‐element block [a, b, c], emit [b, c, a].
            result.push(chunk[1]);
            result.push(chunk[2]);
            result.push(chunk[0]);
        } else {
            // Tail of length 1 or 2: leave unchanged.
            result.extend_from_slice(chunk);
        }
    }
    result
}

